const assets='../../../../public/art/characters/';
const scenes={combat:'Бой',map:'Карта похода',reward:'Выбор формы',inventory:'Сборка',result:'После боя',shop:'Торговец',camp:'Лагерь',settings:'Настройки'};
const beforeFiles={combat:'current-combat-1280.png',map:'current-dense-map-1280.png',reward:'current-reward-1280.png',inventory:'current-dense-map-1280.png',result:'current-result-1280.png',shop:'current-shop-1280.png',camp:'current-camp-1280.png',settings:'current-node-1280.png'};
const glyphs={edge:'<path d="m9 25 8-20 6 20-7-5z"/><path d="M7 28h18"/>',arm:'<path d="M5 16h22m-5-5 5 5-5 5M10 11l-5 5 5 5"/>',pierce:'<path d="M5 27 26 6m-11 0h11v11M7 14l4 4"/>',fire:'<path d="M16 3c2 8 9 9 9 17a9 9 0 0 1-18 0c0-4 3-6 4-8 0 6 6 4 5-9Z"/>',return:'<path d="M26 23H13a8 8 0 0 1 0-16h10M18 3l6 4-6 5"/>',cold:'<path d="M16 3v26M5 10l22 12M5 22 27 10M12 6l4 4 4-4M12 26l4-4 4 4"/>',cut:'<path d="M7 26 24 5l2 8L11 29zm-2-4 8 6"/>',stone:'<path d="m6 23 5-17 14 5 2 13-15 4zM11 6l7 12 9 6M6 23l12-5"/>',heal:'<path d="M12 3h8v7l6 8v9H6v-9l6-8zM16 16v8m-4-4h8"/>',bomb:'<circle cx="15" cy="20" r="9"/><path d="m18 11 3-5h6M23 2v5m4 1 3 1"/>',jump:'<path d="M4 25Q16-8 28 25m-8-3 8 3-1-8M3 29h8m10 0h8"/>',spin:'<path d="M7 10a11 11 0 1 1-2 9M4 4l3 6 6-2"/>',clock:'<circle cx="16" cy="16" r="12"/><path d="M16 7v10l6 3"/>',shield:'<path d="M5 6 16 3l11 3v11q-2 9-11 13Q7 26 5 17z"/>'};
const icon=(id,large=false)=>`<span class="art-icon${large?' large':''}"><svg viewBox="0 0 32 32" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round" stroke-linecap="round">${glyphs[id]||glyphs.edge}</svg></span>`;
const rawIcon=id=>`<svg viewBox="0 0 32 32" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round" stroke-linecap="round">${glyphs[id]||glyphs.edge}</svg>`;
const items={
 catch:{name:'Улов',kind:'Талисман',icon:'jump',effect:'Цепь, убившая 3+ врагов: следующий прыжок за 5 с бесплатен.',help:'Прыгни после успешной цепи, пока действует бесплатный прыжок.'},
 edge:{name:'Острие',kind:'Талисман',icon:'edge',effect:'3-е звено цепи получает +2 силы перед ударом.',help:'Собирай цепь так, чтобы усиленное звено пришлось на крепкого противника.'},
 arm:{name:'Длинная рука',kind:'Талисман',icon:'arm',effect:'С 3-го звена цепи радиус звена ×1,5.',help:'После первых двух звеньев становятся доступны более далёкие цели.'},
 pierce:{name:'Прямая',kind:'Форма · Конец',icon:'pierce',effect:'Прямой хвост цепи: проход продолжится по прямой и ударит всех на пути.',help:'Выбирай направление последних звеньев: оно задаёт направление пробоя.'},
 return:{name:'Возврат',kind:'Форма · Путь',icon:'return',effect:'После прохода герой бежит к началу цепи с половиной силы; неуязвим на бегу.',help:'Конец первого прохода не станет твоей окончательной позицией.'},
 fire:{name:'Огненный проход',kind:'Форма · Путь',icon:'fire',effect:'Цепь из 3+ звеньев: путь горит 2 с. Вошедший враг получает 1 урон.',help:'Полезен, когда за первой группой по тому же пути идёт следующая.'},
 cut:{name:'Режущий проход',kind:'Форма · Путь',icon:'cut',effect:'Проход бьёт на 1 врагов любого цвета в 0,5 от пути, кроме звеньев цепи.',help:'Прокладывай путь рядом с врагами другого цвета.'},
 cold:{name:'Наледь',kind:'Форма · Путь',icon:'cold',effect:'Путь прохода 2 с морозит врагов, которые в него входят.',help:'Оставляет замедляющий продвижение врагов путь после атаки.'},
 millstone:{name:'Жернов',kind:'Реликвия',icon:'stone',effect:'Смена цвета после 4 звеньев одного цвета вместо 6.',cost:'Максимум HP −3.',help:'Более ранняя смена цвета ценой запаса здоровья.'},
 whetstone:{name:'Точильный камень',kind:'Талисман',icon:'stone',effect:'Первая цепь каждой арены начинается с силой 1.',help:'Бонус действует на первую цепь боя.'}
};
const state={screen:'combat',returnTo:'combat',item:'edge',offer:'fire',node:0,hero:'cat',npc:null,pause:false,confirm:false,before:false,forecast:false,aim:null,details:false,knack:null,path:'return',resources:9,hp:12,heals:2,bombs:1,healBought:0,shopBought:[],shopSelected:'bomb',font:100,contrast:false,motion:true,search:'',toast:''};
const game=$('game');let toastTimer;
const button=(text,action,cls='secondary',more='')=>`<button class="${cls}" data-action="${action}" ${more}>${text}</button>`;
const heroName=()=>state.hero==='cat'?'Кот':'Ведунья';
function topbar(place){if(state.screen==='camp'||state.screen==='settings'&&state.returnTo==='camp')return `<header class="topbar"><span class="place">${place}</span><span class="resource">◇ 60 <small>запас лагеря</small></span><span class="spacer"></span>${button(state.screen==='camp'?'Настройки <kbd>Esc</kbd>':'Назад <kbd>Esc</kbd>',state.screen==='camp'?'settings':'back','quiet')}</header>`;return `<header class="topbar"><span class="place">${place}</span><span class="hp">HP ${state.hp} / 18</span><span class="resource">◇ ${state.resources} <small>ресурсов</small></span><span class="spacer"></span>${state.screen!=='inventory'?button('Сборка <kbd>I</kbd>','inventory','quiet'):''}${state.screen!=='settings'?button('Настройки <kbd>Esc</kbd>','settings','quiet'):button('Назад <kbd>Esc</kbd>','back','quiet')}</header>`}
function combat(){const action=(id,key,title,count,price)=>`<button class="action${count===0?' empty':''}${state.aim===id?' selected':''}" data-action="ability" data-id="${id}" aria-label="${title}${count!==null?', осталось '+count:''}" ${count===0?'disabled':''}>${rawIcon(id)}<span class="key">${key}</span><span class="count">${count===null?price+' ⚡':count}</span><span class="label">${title}</span></button>`;return `<section class="combat"><img class="arena-image" src="field-only.png" alt="Поле текущей игры: статичный кадр для размещения интерфейса"><div class="combat-ui"><div class="hero-vitals"><img class="portrait" src="${assets}${state.hero==='cat'?'player':'toad'}.png" alt=""><div class="vitals-text"><div class="row between"><span>${heroName()}</span><span class="hp-value">${state.hp}<small> / 18</small></span></div><div class="health-track"><i style="width:${state.hp/18*100}%"></i></div></div></div><div class="combat-goal"><small>ПОЛЯНА · ЦЕЛЬ БОЯ</small><strong>Уничтожить врагов · 14 / 20</strong></div><div class="combat-menu">${button('Сборка <kbd>I</kbd>','inventory','quiet')}${button('Пауза <kbd>Esc</kbd>','pause','quiet')}</div><div class="combat-build"><button data-action="inspect" data-id="edge" aria-label="Острие, открыть описание">${icon('edge')}<span>Острие<br><b>3-е · +2</b></span></button><button data-action="inspect" data-id="arm" aria-label="Длинная рука, открыть описание">${icon('arm')}<span>Рука<br><b>с 3-го</b></span></button></div>${state.forecast?'<div class="forecast"><small>ПРОГНОЗ ЦЕПИ</small><strong>4 звена → 3 убийства</strong><span>Последний враг выживет: 2 HP</span><div class="focus-track"><i></i></div><small>Фокус · осталось 1,2 с</small></div>':''}${state.aim?`<div class="aim-hint">${state.aim==='jump'?'Выбери место прыжка':'Выбери врага'} · <kbd>ЛКМ</kbd> применить · <kbd>Esc</kbd> отменить</div>`:''}<div class="action-zone"><div class="energy-line"><span>Энергия <b>3 / 7</b></span><span class="energy-pips">${Array.from({length:7},(_,i)=>`<i class="${i<3?'on':''}"></i>`).join('')}</span></div><div class="actions">${action('jump','Пробел','Прыжок',null,2)}${action('spin','Q','Круговой',null,3)}<span class="action-divider"></span>${action('cold','1','Холод',0)}${action('bomb','2','Бомба',state.bombs)}${action('heal','3','Лечение',state.heals)}${action('fire','4','Огонь',0)}</div></div><div class="combat-help"><kbd>WASD</kbd> движение<br><kbd>ЛКМ</kbd> цепь · <kbd>ПКМ</kbd> отмена</div></div></section>`}
const nodeTypes={battle:'⚔',rest:'☾',event:'?',hard:'◆',shop:'⚖',boss:'♜'};
const mapNodes=[{x:5,y:50,t:'current'},...[-1,0,1].map((n,i)=>({x:20,y:50+n*27,t:'battle',available:i})),{x:35,y:23,t:'event'},{x:35,y:50,t:'battle'},{x:35,y:77,t:'rest'},{x:50,y:35,t:'battle'},{x:50,y:65,t:'hard'},{x:64,y:50,t:'boss'},{x:78,y:23,t:'rest'},{x:78,y:50,t:'shop'},{x:78,y:77,t:'battle'},{x:93,y:35,t:'boss'},{x:93,y:65,t:'boss'}];
const edges=[[0,1],[0,2],[0,3],[1,4],[2,4],[2,5],[3,6],[4,7],[5,7],[5,8],[6,8],[7,9],[8,9],[9,10],[9,11],[9,12],[10,13],[11,13],[11,14],[12,14]];
const destinations=[{name:'Поляна',goal:'Уничтожить 20 врагов',terrain:'Открытая площадка, деревья и пруд',meaning:'Обычный бой. Награда зависит от результата боя.'},{name:'Прогалина',goal:'Уничтожить 25 врагов',terrain:'Широкий двор с выступами стен',meaning:'Обычный бой. Выбери удобную сторону подхода.'},{name:'Жаровни',goal:'Уничтожить 25 врагов',terrain:'Жаровни на пути цепи',meaning:'Огонь усиливает следующие звенья цепи.'}];
function mapScreen(){const d=destinations[state.node];return topbar('Лес')+`<div class="map-layout"><div class="map-left"><div class="map-title"><div><div class="eyebrow">Следующий шаг</div><h1>Выбери путь</h1><p class="muted">Три доступных боя. Вход — после подтверждения.</p></div>${button('Лечение +'+Math.max(0,Math.min(2,18-state.hp))+' HP · '+(2+state.healBought)+' ◇','map-heal','secondary',state.hp>=18||state.resources<2+state.healBought?'disabled':'')}</div><div class="route-map" aria-label="Карта маршрутов"><svg viewBox="0 0 1000 500" preserveAspectRatio="none" aria-hidden="true">${edges.map(([a,b])=>`<path d="M${mapNodes[a].x*10} ${mapNodes[a].y*5}L${mapNodes[b].x*10} ${mapNodes[b].y*5}" stroke="${a===0?'#baa674':'#516663'}" stroke-width="2" fill="none"/>`).join('')}</svg>${mapNodes.map((n,i)=>`<button class="node ${n.t==='current'?'current':''} ${n.available!==undefined?'available':''} ${n.available===state.node?'chosen':''}" style="left:${n.x}%;top:${n.y}%" ${n.available===undefined?'disabled':`data-action="node" data-id="${n.available}" aria-pressed="${n.available===state.node}"`} aria-label="${n.available!==undefined?destinations[n.available].name:'Недоступный узел'}">${n.t==='current'?'✓':nodeTypes[n.t]}${i===0?'<span class="node-caption">Ты здесь</span>':''}</button>`).join('')}</div><div class="map-legend"><span>⚔ Бой</span><span>◆ Трудный бой</span><span>☾ Привал</span><span>⚖ Торговец</span><span>? Событие</span><span>♜ Босс</span></div></div><aside class="panel map-card"><div class="map-card-content"><div class="eyebrow">Выбранный узел · бой</div><h2>${d.name}</h2><p class="muted">${d.meaning}</p><div class="arena-mini" aria-hidden="true"><svg viewBox="0 0 260 110"><rect x="2" y="2" width="256" height="106" rx="4" fill="#344a37" stroke="#b2b393"/><rect x="58" y="20" width="12" height="36" fill="#778275"/><rect x="175" y="70" width="42" height="12" fill="#778275"/><circle cx="201" cy="30" r="17" fill="#658f91"/><circle cx="121" cy="66" r="6" fill="#d5b679"/><path d="M116 66h10" stroke="#27313a" stroke-width="2"/><circle cx="92" cy="32" r="5" fill="#96bab8"/><circle cx="145" cy="37" r="5" fill="#96bab8"/></svg></div><div class="info-row"><small>Цель</small><strong>${d.goal}</strong></div><div class="info-row"><small>Противники</small><span class="enemy-dot"></span>Обычные</div><div class="info-row"><small>Местность</small>${d.terrain}</div></div>${button('В бой <kbd>Enter</kbd>','enter','primary')}</aside></div>`}
function rewardScreen(){const a=items[state.offer],old=items[state.path];return topbar('Награда')+`<div class="screen-body"><div class="page-heading"><div><div class="eyebrow">Форма цепи · Путь</div><h1>Как изменится твой проход?</h1><p class="muted">Выбери одну форму. Перед заменой можно сравнить эффекты.</p></div><span class="chip">Сейчас: ${old.name}</span></div><div class="reward-layout"><div class="offers">${['fire','cut','cold'].map(id=>`<button class="offer ${state.offer===id?'selected':''}" data-action="offer" data-id="${id}" aria-pressed="${state.offer===id}">${icon(items[id].icon,true)}<span class="offer-kind">${items[id].kind}</span><h3>${items[id].name}</h3><p>${items[id].effect}</p><span class="selected-text">${state.offer===id?'✓ Выбрано для сравнения':'Нажми, чтобы сравнить'}</span></button>`).join('')}</div><aside class="panel comparison"><div class="eyebrow">Изменение сборки</div><div class="compare-part"><small class="muted">Уйдёт · Путь</small><h3>${old.name}</h3><p>${old.effect}</p></div><span class="compare-arrow">↓</span><div class="compare-part"><small class="good">Получишь · Путь</small><h3>${a.name}</h3><p>${a.effect}</p></div><div class="notice">Остальные предметы сохраняются.</div></aside></div><div class="reward-footer"><p>Не выбранные формы могут встретиться снова.</p><div class="row">${button('Отказаться','skip-reward','quiet')}${button('Взять «'+a.name+'»','take-reward','primary')}</div></div></div>`}
function inventory(){const a=items[state.item];const groups=[['Формы цепи',['pierce',state.path]],['Талисманы',['edge','arm',...(state.knackTaken==='catch'?['catch']:[]),...(state.shopBought.includes('whetstone')?['whetstone']:[])]],['Реликвии',['millstone']]];return topbar('Сборка')+`<div class="screen-body"><div class="page-heading"><div><div class="eyebrow">${heroName()} · текущий поход</div><h1>Что умеет твоя цепь</h1></div><div class="row"><input class="search" id="item-search" value="${esc(state.search)}" placeholder="Название или эффект" aria-label="Найти предмет">${button('Назад <kbd>Esc</kbd>','back','secondary')}</div></div><div class="inventory-layout"><div class="inventory-list">${groups.map(([name,ids])=>`<section class="inventory-group"><h3>${name}</h3>${ids.filter(id=>(items[id].name+' '+items[id].effect).toLowerCase().includes(state.search.toLowerCase())).map(id=>`<button class="item-row ${id===state.item?'selected':''}" data-action="item" data-id="${id}" aria-pressed="${id===state.item}">${icon(items[id].icon)}<span class="grow"><strong>${items[id].name}</strong><small>${items[id].effect}</small></span>${id==='arm'||id==='pierce'?'<span class="badge">Есть сплав</span>':''}</button>`).join('')}</section>`).join('')}${!groups.some(([,ids])=>ids.some(id=>(items[id].name+' '+items[id].effect).toLowerCase().includes(state.search.toLowerCase())))?'<p class="muted">Ничего не найдено</p>':''}</div><aside class="panel item-detail">${icon(a.icon,true)}<h2>${a.name}</h2><p>${a.effect}</p>${a.cost?`<div class="notice bad">Цена: ${a.cost}</div>`:''}<div class="detail-label">Как использовать</div><p>${a.help}</p>${['arm','pierce'].includes(state.item)?'<div class="detail-label">Сплав доступен на привале</div><div class="synergy"><strong>Прямая + Длинная рука → Копьё</strong><p>Пробой вдвое длиннее; снимает 2 пластины. Радиус с 3-го звена сохраняется.</p><small>Займёт привал вместо лечения или крафта.</small></div>':''}<div class="detail-label">Происхождение</div><p class="muted">Текущий поход · ${a.kind}</p></aside></div></div>`}
const shopGoods={bomb:{name:'Бомба',icon:'bomb',price:3,effect:'Один расходник. Наносит выбранному врагу 6 урона; снимает 2 пластины.',gain:'Бомб: 1 → 2'},healing:{name:'Лечение',icon:'heal',price:3,effect:'Зелье восстанавливает до 9 HP в бою. В руке не больше 3 зелий.',gain:'Зелий: 2 → 3'},whetstone:{name:'Точильный камень',icon:'stone',price:4,effect:items.whetstone.effect,gain:'Добавится в талисманы'}};
function shop(){const a=shopGoods[state.shopSelected],bought=state.shopBought.includes(state.shopSelected),full=state.shopSelected==='healing'&&state.heals>=3;return topbar('Торговец')+`<div class="screen-body"><div class="page-heading"><div><div class="eyebrow">Покупка за ресурсы</div><h1>Выбирай с запасом на путь</h1><p class="muted">Цена и остаток ресурсов видны до покупки.</p></div><span class="chip">◇ ${state.resources} ресурсов</span></div><div class="reward-layout"><div class="offers">${Object.entries(shopGoods).map(([id,g])=>`<button class="offer ${state.shopSelected===id?'selected':''}" data-action="shop-item" data-id="${id}" aria-pressed="${state.shopSelected===id}">${icon(g.icon,true)}<span class="offer-kind">${id==='whetstone'?'Талисман':'Расходник'}</span><h3>${g.name}</h3><p>${g.effect}</p><strong class="good">${state.shopBought.includes(id)?'✓ Куплено':g.price+' ◇'}</strong></button>`).join('')}</div><aside class="panel comparison"><div class="eyebrow">Перед покупкой</div><h2>${a.name}</h2><div class="compare-part"><small class="muted">В запасе</small><p>${bought?'Товар уже куплен':state.shopSelected==='healing'?'Зелий: '+state.heals+' → '+Math.min(3,state.heals+1):state.shopSelected==='bomb'?'Бомб: '+state.bombs+' → '+(state.bombs+1):a.gain}</p></div><div class="compare-part"><small class="muted">Ресурсы</small><p><strong>${state.resources} → ${bought?state.resources:Math.max(0,state.resources-a.price)}</strong></p></div><p class="muted">${bought?'Этот товар больше недоступен.':full?'Рука полна: 3 зелья.':state.resources<a.price?'Не хватает '+(a.price-state.resources)+' ресурсов.':'Покупка применится после подтверждения.'}</p></aside></div><div class="reward-footer">${button('Уйти к карте','map','secondary')}${button(bought?'Куплено':'Купить за '+a.price+' ◇','buy','primary',bought||full||state.resources<a.price?'disabled':'')}</div></div>`}
function result(){return topbar('Бой завершён')+`<div class="screen-body"><div class="page-heading"><div><div class="eyebrow">Поляна · победа</div><h1>Путь свободен</h1><p class="muted">Результаты боя и следующий выбор — на одном экране.</p></div><span class="chip">HP ${state.hp} / 18</span></div><div class="result-grid"><section class="panel"><h2>Результат боя</h2><div class="summary-numbers"><div><strong>0:48</strong><small>время</small></div><div><strong>27</strong><small>убито</small></div><div><strong>8</strong><small>лучшая цепь</small></div></div><div class="result-reward">${icon('stone')}<span><strong>Ресурсы сохранены в походе</strong><br><small class="muted">Текущий запас: ${state.resources}</small></span></div>${button(state.details?'Скрыть подробности':'Подробности боя','details','details-toggle')}${state.details?'<p class="details-text">Урон получен: 6 · цель выполнена.<br>Подробный журнал доступен отдельно от основного результата.</p>':''}</section><section class="panel"><div class="eyebrow">Сноровка · выбери улучшение</div><h2>Усиль знакомый приём</h2><div class="stack" style="margin-top:20px">${['edge','catch'].map(id=>`<button class="knack-card ${state.knack===id?'selected':''}" data-action="knack" data-id="${id}" aria-pressed="${state.knack===id}">${icon(id)}<span><strong>${items[id].name} · ${id==='edge'?'ранг II':'новый талисман'}</strong><p>${id==='edge'?'Каждое 3-е звено (3, 6, 9…) получает +2 силы.':items.catch.effect}</p></span></button>`).join('')}</div><div class="footer-actions">${button('Пропустить','map','quiet')}${button('Взять и к карте','take-knack','primary',state.knack?'':'disabled')}</div></section></div></div>`}
const npcs={owl:{name:'Неясыть',art:'npc-owl',role:'Пути и бестиарий',text:'Сведения о встреченных противниках и улучшения подготовки к походу.'},herb:{name:'Марфа',art:'npc-herbalist',role:'Расходники в дорогу',text:'Подготовка расходников. Покупки лагеря улучшают удобство похода.'},smith:{name:'Ерофей',art:'npc-smith',role:'Правка и перебросы',text:'Улучшения выбора наград. Сначала посмотри эффект и цену.'}};
function camp(){const n=state.npc?npcDialogs[state.npc]:null;return `<section class="camp"><div class="camp-bg"></div><div class="camp-shade"></div>${topbar('Очаг')}<div class="camp-content"><section class="hero-sheet"><div class="eyebrow">Герой следующего похода</div><h1>${heroName()}</h1><p>${state.hero==='cat'?'Формы находит в походе.<br>Щит — после трёх убийств.':'Кольцо с первого боя.<br>Щит — только после кольца.'}</p><div class="hero-switch">${['cat','toad'].map(id=>`<button class="${state.hero===id?'chosen':''}" data-action="hero" data-id="${id}" aria-pressed="${state.hero===id}"><img src="${assets}${id==='cat'?'player':'toad'}.png" alt=""><span>${id==='cat'?'Кот':'Ведунья'}</span></button>`).join('')}</div><div class="row between"><small class="muted">До следующего набора</small><small>5 / 60</small></div><div class="health-track"><i></i></div>${button('В поход →','start-run','primary')}<p class="screen-note">Дар и подготовка — перед первым боем.</p></section><div class="camp-world"><img class="camp-hero" src="${assets}${state.hero==='cat'?'player':'toad'}.png" alt="${heroName()}"><span class="camp-world-label">У огня спокойно</span></div><aside class="residents"><div class="eyebrow">Жители лагеря</div>${Object.entries(npcs).map(([id,n])=>`<button class="resident ${state.npc===id?'selected':''}" data-action="npc" data-id="${id}" aria-expanded="${state.npc===id}"><img src="${assets}${n.art}.png" alt=""><span><strong>${n.name}</strong><small>${n.role}</small></span></button>`).join('')}${n?`<div class="npc-card"><h3>${npcs[state.npc].name}</h3><p>${npcs[state.npc].text}</p></div>`:''}</aside></div></section>`}
const npcDialogs={owl:true,herb:true,smith:true};
function settings(){return topbar('Настройки')+`<div class="screen-body"><div class="page-heading"><div><div class="eyebrow">ПК · мышь и клавиатура</div><h1>Сделай интерфейс удобным</h1></div><span class="chip">Применяется к макету</span></div><div class="settings-grid"><section class="panel"><h2>Читаемость</h2><label class="setting"><span><strong>Размер текста</strong><small>Карточки и описания предметов</small></span><select id="font-size" aria-label="Размер текста">${[100,110,120].map(n=>`<option value="${n}" ${state.font===n?'selected':''}>${n}%</option>`).join('')}</select></label><label class="setting"><span><strong>Повышенный контраст</strong><small>Текст и границы панелей</small></span><input id="contrast" type="checkbox" ${state.contrast?'checked':''}></label><label class="setting"><span><strong>Движение интерфейса</strong><small>Плавное появление подсказок</small></span><input id="motion" type="checkbox" ${state.motion?'checked':''}></label><div class="notice">${items.edge.effect}</div><p class="screen-note">Полное переназначение управления — в предложении; здесь показаны назначенные клавиши.</p></section><section class="panel"><h2>Управление</h2>${[['Передвижение','W A S D'],['Цепь','ЛКМ'],['Отмена прицеливания','ПКМ / Esc'],['Прыжок','Пробел'],['Круговой удар','Q'],['Расходники','1 – 4'],['Сборка','I'],['Пауза / назад','Esc / P']].map(([a,b])=>`<div class="key-row"><span>${a}</span><kbd>${b}</kbd></div>`).join('')}</section></div><div class="footer-actions"><span class="muted">Изменения видны сразу.</span>${button('Готово','back','primary')}</div></div>`}
function modal(){if(state.confirm)return `<div class="modal-backdrop"><section class="pause-panel" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">Прервать поход?</h2><p>Текущий поход будет завершён. Вернуться в этот бой уже не получится.</p>${button('Остаться','cancel-exit','primary')}${button('Прервать поход','confirm-exit','secondary danger')}</section></div>`;return `<div class="modal-backdrop"><section class="pause-panel" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="eyebrow">Бой приостановлен</div><h2 id="dialog-title">Пауза</h2><p>Поляна · ${heroName()}</p>${button('Продолжить <kbd>Esc</kbd>','resume','primary')}${button('Сборка <kbd>I</kbd>','inventory','secondary')}${button('Настройки','settings','secondary')}${button('Прервать поход','exit','quiet danger')}</section></div>`}
const renderers={combat,map:mapScreen,reward:rewardScreen,inventory,result,shop,camp,settings};
function render(focusAction){const prev=document.activeElement;const prevAction=prev?.dataset?.action,prevId=prev?.dataset?.id;document.body.classList.toggle('no-motion',!state.motion);document.documentElement.style.setProperty('--ui',state.font/100);document.body.classList.toggle('high-contrast',state.contrast);game.innerHTML=renderers[state.screen]()+`<div class="watermark">CODEX · КОНЦЕПТ UI</div>`+(state.pause||state.confirm?modal():'')+(state.before?`<div class="before"><img src="${beforeFiles[state.screen]}" alt="Текущий интерфейс"><button class="before-label" data-action="before">Текущий интерфейс · вернуться к предложению</button></div>`:'')+(state.toast?`<div class="toast" role="status">${esc(state.toast)}</div>`:'');$('scene').value=state.screen;$('forecast-control').hidden=state.screen!=='combat';$('compare').hidden=state.screen==='settings'||state.screen==='inventory';document.title='Ashen Oath · '+scenes[state.screen]+' · концепт UI';history.replaceState(null,'','#'+state.screen);const f=focusAction?game.querySelector(`[data-action="${focusAction}"]`):state.pause||state.confirm?game.querySelector('.pause-panel button'):null;if(f)f.focus({preventScroll:true});else if(prevAction){const target=[...game.querySelectorAll('[data-action]')].find(b=>b.dataset.action===prevAction&&b.dataset.id===prevId&&!b.disabled);target?.focus({preventScroll:true});}}
const menuStack=[];
function go(screen){if(screen===state.screen)return;if(screen==='inventory'||screen==='settings'){menuStack.push({screen:state.screen,pause:state.pause});if(state.screen!=='inventory'&&state.screen!=='settings')state.returnTo=state.screen;}else menuStack.length=0;state.screen=screen;state.pause=false;state.confirm=false;state.before=false;state.aim=null;render();const heading=game.querySelector('h1,.combat-menu button');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true})}}
function back(){const previous=menuStack.pop()||{screen:state.returnTo,pause:false};state.screen=previous.screen;state.pause=previous.pause;state.confirm=false;render(state.pause?'resume':state.screen==='combat'?'inventory':undefined);}
function notify(text){state.toast=text;clearTimeout(toastTimer);render();toastTimer=setTimeout(()=>{state.toast='';game.querySelector('.toast')?.remove()},2500);}
function act(action,id){switch(action){case'combat':case'map':case'camp':case'reward':case'shop':case'result':go(action);break;case'inventory':case'settings':go(action);break;case'back':back();break;case'pause':state.pause=true;state.aim=null;render('resume');break;case'resume':state.pause=false;render('pause');break;case'exit':state.confirm=true;render('cancel-exit');break;case'cancel-exit':state.confirm=false;render('resume');break;case'confirm-exit':state.pause=false;state.confirm=false;go('camp');break;case'node':state.node=Number(id);render('enter');break;case'enter':go('combat');break;case'offer':state.offer=id;render();game.querySelector(`[data-action="offer"][data-id="${id}"]`).focus();break;case'take-reward':state.path=state.offer;go('map');notify('Получено: '+items[state.path].name);break;case'skip-reward':go('map');break;case'item':state.item=id;render();game.querySelector(`[data-action="item"][data-id="${id}"]`).focus();break;case'inspect':state.item=id;go('inventory');break;case'details':state.details=!state.details;render('details');break;case'knack':state.knack=id;render('take-knack');break;case'take-knack':state.knackTaken=state.knack;if(state.knack==='edge')items.edge.effect='Ранг II: каждое 3-е звено (3, 6, 9…) получает +2 силы перед ударом.';go('map');notify((state.knack==='edge'?'Ранг II: ':'Получено: ')+items[state.knack].name);break;case'shop-item':state.shopSelected=id;render('buy');break;case'buy':{const a=shopGoods[state.shopSelected];if(state.shopBought.includes(state.shopSelected)||state.resources<a.price||state.shopSelected==='healing'&&state.heals>=3)break;state.resources-=a.price;state.shopBought.push(state.shopSelected);if(state.shopSelected==='healing')state.heals++;if(state.shopSelected==='bomb')state.bombs++;notify('Куплено: '+a.name);break;}case'map-heal':if(state.hp<18&&state.resources>=2+state.healBought){state.resources-=2+state.healBought;state.healBought++;state.hp=Math.min(18,state.hp+2);render('map-heal')}break;case'hero':state.hero=id;render();break;case'npc':state.npc=state.npc===id?null:id;render();break;case'npc-info':notify('Макет показывает вход к '+npcs[state.npc].name+'. Таблицы покупок сохраняются по текущим правилам.');break;case'start-run':go('map');break;case'ability':if(id==='heal'){if(state.heals>0&&state.hp<18){state.heals--;state.hp=Math.min(18,state.hp+9);notify('Пример: зелье применено')}}else if(id==='spin')notify('Круговой удар · здесь показан только интерфейс');else{state.aim=state.aim===id?null:id;render()}break;case'before':state.before=!state.before;render();break;}}
game.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)act(b.dataset.action,b.dataset.id)});
game.addEventListener('input',e=>{if(e.target.id==='item-search'){const at=e.target.selectionStart;state.search=e.target.value;render();$('item-search').focus();$('item-search').setSelectionRange(at,at)}});
game.addEventListener('change',e=>{if(e.target.id==='font-size')state.font=Number(e.target.value);if(e.target.id==='contrast')state.contrast=e.target.checked;if(e.target.id==='motion')state.motion=e.target.checked;render();const target=$(e.target.id);if(target)target.focus()});
$('scene').innerHTML=Object.entries(scenes).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');$('scene').onchange=e=>go(e.target.value);$('compare').onclick=()=>act('before');$('forecast-control').onclick=()=>{state.forecast=!state.forecast;render()};
window.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')&&e.key!=='Escape')return;if(e.key==='Tab'&&(state.pause||state.confirm)){const buttons=[...game.querySelectorAll('.pause-panel button')];if(e.shiftKey&&document.activeElement===buttons[0]){e.preventDefault();buttons.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===buttons.at(-1)){e.preventDefault();buttons[0].focus()}return}if(e.key==='Escape'){e.preventDefault();if(state.before){state.before=false;render();return}if(state.confirm){act('cancel-exit');return}if(state.pause){act('resume');return}if(state.aim){state.aim=null;render();return}if(state.screen==='combat'){act('pause');return}if(['inventory','settings'].includes(state.screen)){act('back');return}if(state.screen==='camp'&&state.npc){state.npc=null;render();return}go('settings');return}if(e.code==='KeyI'&&state.screen!=='camp'&&!(state.screen==='settings'&&state.returnTo==='camp')){e.preventDefault();state.screen==='inventory'?act('back'):go('inventory');return}if(e.code==='KeyP'&&state.screen==='combat'){state.pause?act('resume'):act('pause');return}if(e.key==='Enter'&&state.screen==='map'&&e.target===document.body){act('enter');return}if(state.screen==='combat'&&!state.pause&&!state.confirm){const id={Space:'jump',KeyQ:'spin',Digit2:'bomb',Digit3:'heal'}[e.code];if(id){e.preventDefault();act('ability',id)}}});
window.addEventListener('hashchange',()=>{const s=location.hash.slice(1);if(scenes[s])go(s)});
if(new URLSearchParams(location.search).has('present'))document.body.classList.add('present');
const initial=location.hash.slice(1);if(scenes[initial])state.screen=initial;render();
